def _fit_one_by_one(chunk, spec):
    """The sequential path, used when a batch contains a singular system: same estimators as 1.x."""
    count = chunk.shape[0]
    betas_y = np.zeros((count, len(spec.exog_inds_y)))
    betas_m = np.zeros((len(spec.inds_m), count, len(spec.exog_inds_m)))
    failed = np.zeros(count, dtype=bool)
    for i in range(count):
        sample = chunk[i]
        try:
            betas_y[i] = fit_outcome(
                sample[:, spec.ind_y], sample[:, spec.exog_inds_y], spec.family, spec.max_iter, spec.tolerance
            )
            for j, ind in enumerate(spec.inds_m):
                betas_m[j, i] = fast_OLS(sample[:, ind], sample[:, spec.exog_inds_m])
        except (LinAlgError, ConvergenceError):
            failed[i] = True
    return betas_y, betas_m, failed

def _raw_indirect_draws(self):
    """Labels, estimates and bootstrap draws of the total (if requested) and of every path."""
    e = np.array([self._path_effect(p, self._true_betas_y, self._true_betas_m) for p in self._paths])
    be = np.array([self._path_effect(p, self._boot_betas_y, self._boot_betas_m) for p in self._paths])
    labels = [term for component, term in self.effect_labels if component != "contrast"]
    if self._options["total"]:
        e = np.concatenate([[e.sum()], e])
        be = np.concatenate([be.sum(axis=0, keepdims=True), be])
    return labels, e, be

