def msm_transformation(density_ratio, propensity):
    # transpose propensity to shape (1, n_data)
    propensity = torch.transpose(propensity, 0, 1)
    return (density_ratio - propensity) / (1 - propensity)

@staticmethod
def sensitivity_constraint_msm(p_u_x, p_u_xa, propensity):
    ratio_msm = SensitivityModel.msm_transformation(p_u_x / p_u_xa, propensity)
    max_ratio1 = torch.max(ratio_msm, dim=0, keepdim=True)[0]
    max_ratio2 = torch.max(1 / ratio_msm, dim=0, keepdim=True)[0]
    return torch.maximum(max_ratio1, max_ratio2)

@staticmethod
def sensitivity_constraint_cmsm(p_u_x, p_u_xa, propensity):
    max_ratio1 = torch.max(p_u_x / p_u_xa, dim=0, keepdim=True)[0]
    max_ratio2 = torch.max(p_u_xa / p_u_x, dim=0, keepdim=True)[0]
    return torch.maximum(max_ratio1, max_ratio2)

# f sensitivity models
@staticmethod
def sensitivity_constraint_f_binary(p_u_x, p_u_xa, propensity, f):
    ratio_msm = SensitivityModel.msm_transformation(p_u_x / p_u_xa, propensity)
    ratio1 = torch.mean(f(ratio_msm), dim=0, keepdim=True)
    ratio2 = torch.mean(f(1 / ratio_msm), dim=0, keepdim=True)
    return torch.maximum(ratio1, ratio2)

@staticmethod
def sensitivity_constraint_f_continuous(p_u_x, p_u_xa, propensity, f):
    ratio1 = torch.mean(f(p_u_x / p_u_xa), dim=0, keepdim=True)
    ratio2 = torch.mean(f(p_u_xa / p_u_x), dim=0, keepdim=True)
    return torch.maximum(ratio1, ratio2)

# Generalized marginal sensitivity model for a single binary treatment
class GMSM_binary(GMSM):
    def __init__(self, causal_graph, y_type, models=None, scaling_params=None):
        super().__init__(causal_graph, y_type, models=models, scaling_params=scaling_params)

    def get_s(self, key, data: GSM_Dataset, gammas):
        # Calculate s- for a given key in M or Y
        if "propensity" not in self.models.keys():
            raise Exception("Propensity model not trained")
        a = data.data["a"].to(torch.int64)
        prop1 = self.predict_by_key("propensity", data)
        prop = torch.concat((1 - prop1, prop1), dim=1)
        prop_a = prop.gather(1, a)
        gammas = gammas.repeat(prop_a.size(0), 1)
        s_minus = 1 / ((1 - gammas) * prop_a + gammas)
        s_plus = 1 / ((1 - (1 / gammas)) * prop_a + (1 / gammas))
        #Outputs are of size n x len(gammas)
        return {"s_minus": s_minus, "s_plus": s_plus}


class GMSM_continuous(GMSM):
    def __init__(self, causal_graph, y_type, models=None, scaling_params=None):
        super().__init__(causal_graph, y_type, models=models, scaling_params=scaling_params)

    def get_s(self, key, data: GSM_Dataset, gammas):
        # Calculate s- for a given key in M or Y
        a = data.data["a"]
        gammas = gammas.repeat(a.size(0), 1)
        s_minus = 1 / gammas
        s_plus = gammas
        #Outputs are of size n x len(gammas)
        return {"s_minus": s_minus, "s_plus": s_plus}


class GMSM_weighted(GMSM):
    def __init__(self, causal_graph, y_type, weight_function, models=None, scaling_params=None):
        super().__init__(causal_graph, y_type, models=models, scaling_params=scaling_params)
        self.weight_function = weight_function

    def get_s(self, key, data: GSM_Dataset, gammas):
        weights = self.weight_function(data)
        # Calculate s- for a given key in M or Y
        gammas = gammas.repeat(weights.size(0), 1)
        s_minus = 1 / ((1 - gammas) * weights + gammas)
        s_plus = 1 / ((1 - (1 / gammas)) * weights + (1 / gammas))
        #Outputs are of size n x len(gammas)
        return {"s_minus": s_minus, "s_plus": s_plus}

def get_c(self, key, data: GSM_Dataset, gammas):
    s_dict = self.get_s(key=key, data=data, gammas=gammas)
    c_plus = ((1 - s_dict["s_minus"]) * s_dict["s_plus"]) / (s_dict["s_plus"] - s_dict["s_minus"])
    c_minus = ((1 - s_dict["s_plus"]) * s_dict["s_minus"]) / (s_dict["s_minus"] - s_dict["s_plus"])
    #fill nan values in c_plus and c_minus with 0 (this is the case when Gamma = 1, i.e., no unobserved confounding)
    c_plus[torch.isnan(c_plus)] = 0
    c_minus[torch.isnan(c_minus)] = 0
    return {"c_plus": c_plus, "c_minus": c_minus, "s_plus": s_dict["s_plus"], "s_minus": s_dict["s_minus"]}

def m_combinations(self, m_sizes):
    n = len(m_sizes)
    combinations = [[0] * n]
    for i in range(n):
        if m_sizes[i] == 1:
            feasible_values = [0, 1]
        else:
            feasible_values = [j for j in range(m_sizes[i])]
        new_combinations = []
        for combination in combinations:
            for value in feasible_values:
                new_combination = combination.copy()
                new_combination[i] = value
                new_combinations.append(new_combination)
        combinations = new_combinations
    return combinations

def fit_ensemble(self, config, d_train, d_val=None, y_scale=False, k=5, resample=True):
    # Scaling
    self.scaling_params = {"mean": 0, "sd": 1}
    if y_scale:
        d_train.scale_y()
        if d_val is not None:
            d_val.scale_y()
        self.scaling_params = d_train.scaling_params["y"]
    for i in range(k):
        if resample:
            data_bootstrapped = d_train.get_bootstrapped_dataset(d_train.data["x"].size(0))
        else:
            data_bootstrapped = d_train
        model = self.model_class(self.causal_graph, self.y_type)
        model.fit(config, data_bootstrapped, d_val, y_scale=False)
        if y_scale:
            model.scaling_params = self.scaling_params
        self.ensemble.append(model)

def compute_bounds_ensemble(self, x, gamma_dict, a_int1=1, a_int2=None, n_samples=500, alpha=0.05, q=None, average=False):
    bounds = []
    for model in self.ensemble:
        if a_int2 is None and average is False:
            bounds.append(model.compute_bounds(x, a_int1, gamma_dict, n_samples, q=q))
        elif a_int2 is None and average is True:
            bounds.append(model.compute_bounds_average(x, a_int1, gamma_dict, n_samples, q=q))
        elif a_int2 is not None and average is False:
            bounds.append(model.compute_bounds_difference(x, gamma_dict, n_samples, a_int1, a_int2, q=q))
        elif a_int2 is not None and average is True:
            bounds.append(model.compute_bounds_diff_avg(x, gamma_dict, n_samples, a_int1, a_int2, q=q))
        else:
            raise ValueError("Invalid arguments")
    Q_plus_b = torch.concat([torch.unsqueeze(Q["Q_plus"], 2) for Q in bounds], dim=2)
    Q_minus_b = torch.concat([torch.unsqueeze(Q["Q_minus"], 2) for Q in bounds], dim=2)
    #Compute percentile bootstrap bounds
    Q_plus_upper = torch.quantile(Q_plus_b, 1 - alpha / 2, 2)
    Q_plus_median = torch.quantile(Q_plus_b, 0.5, 2)
    Q_plus_lower = torch.quantile(Q_plus_b, alpha / 2, 2)

    Q_minus_upper = torch.quantile(Q_minus_b, 1 - alpha / 2, 2)
    Q_minus_median = torch.quantile(Q_minus_b, 0.5, 2)
    Q_minus_lower = torch.quantile(Q_minus_b, alpha / 2, 2)

    Q_plus_mean = torch.mean(Q_plus_b, 2)
    Q_plus_std = torch.std(Q_plus_b, 2)
    Q_minus_mean = torch.mean(Q_minus_b, 2)
    Q_minus_std = torch.std(Q_minus_b, 2)

    Q_plus_dict = {"mean": Q_plus_mean, "upper": Q_plus_upper, "lower": Q_plus_lower, "median": Q_plus_median, "std": Q_plus_std}
    Q_minus_dict = {"mean": Q_minus_mean, "upper": Q_minus_upper, "lower": Q_minus_lower, "median": Q_minus_median, "std": Q_minus_std}
